public class StockLinkGameTests {
    private static final BlockPos P=new BlockPos(2,2,3);
    private record Station(PackagerBlockEntity packager,PackagerLinkBlockEntity link,BarrelBlockEntity barrel) {}
    private static Station station(GameTestHelper h,BlockPos pos,UUID network,ItemStack stock) {
        h.setBlock(pos.north(),Blocks.BARREL);var barrel=h.getBlockEntity(pos.north(),BarrelBlockEntity.class);barrel.setItem(0,stock);
        h.setBlock(pos,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));
        h.setBlock(pos.above(),AllBlocks.STOCK_LINK.defaultBlockState().setValue(PackagerLinkBlock.FACE,AttachFace.FLOOR));
        var link=h.getBlockEntity(pos.above(),PackagerLinkBlockEntity.class);link.behaviour.setFrequency(network);link.initialize();
        return new Station(h.getBlockEntity(pos,PackagerBlockEntity.class),link,barrel);
    }
    private static PackageOrderWithCrafts order(Item item,int count) { return new PackageOrderWithCrafts(new PackageOrder(List.of(new BigItemStack(new ItemStack(item),count))),List.of()); }
    private static long boxed(PackagerBlockEntity packager) { long count=PackageItem.getContents(packager.heldBox).stream().mapToLong(ItemStack::getCount).sum();for(var entry:packager.queuedExitingPackages)count+=(long)entry.count*PackageItem.getContents(entry.stack).stream().mapToLong(ItemStack::getCount).sum();return count; }
    @GameTest public void stockLinkRegistersOriginalIdsAndSetsPackagerLinkedMode(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,12));h.assertTrue(s.packager.getBlockState().getValue(PackagerBlock.LINKED),"Attached link enables source linked model");s.packager.activate();h.assertTrue(s.packager.heldBox.isEmpty(),"Linked packager ignores redstone packaging");h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),12,"Linked inventory counted");h.succeed(); }
    @GameTest public void networkSummarySeparatesComponentsAndIndependentNetworks(GameTestHelper h) { var id=UUID.randomUUID();var named=new ItemStack(Items.APPLE,7);named.set(DataComponents.CUSTOM_NAME,Component.literal("Special"));station(h,P,id,named);station(h,P.east(3),UUID.randomUUID(),new ItemStack(Items.APPLE,25));var summary=LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true);h.assertValueEqual(summary.getCountOf(named),7,"Named stock");h.assertValueEqual(summary.getCountOf(new ItemStack(Items.APPLE)),0,"Components not conflated");h.assertValueEqual(summary.contributingLinks,1,"One source network");h.succeed(); }
    @GameTest public void repeatedLinksToOneBarrelDoNotDoubleStockOrRequests(GameTestHelper h) {
        var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,50));var pos=P.north(2);h.setBlock(pos,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.NORTH));h.setBlock(pos.above(),AllBlocks.STOCK_LINK);var second=h.getBlockEntity(pos.above(),PackagerLinkBlockEntity.class);second.behaviour.setFrequency(id);second.initialize();
        h.assertValueEqual(LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true).getCountOf(new ItemStack(Items.APPLE)),50,"Shared barrel counted once");h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),50,"Direct stock counted once");var requests=LogisticsManager.findPackagersForRequest(h.getLevel(),id,order(Items.APPLE,80),null,"Shared");h.assertValueEqual(requests.keySet().size(),1,"One packager represents shared inventory");h.assertValueEqual(requests.values().stream().mapToInt(PackagingRequest::getCount).sum(),50,"No duplicate reservation");h.succeed();
    }
    @GameTest public void ignoredDestinationInventoryCannotRequestFromItself(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,12));h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),s.packager.getIdentifiedInventory()),0,"Destination inventory excluded");h.assertTrue(LogisticsManager.findPackagersForRequest(h.getLevel(),id,order(Items.APPLE,8),s.packager.getIdentifiedInventory(),"Loop").isEmpty(),"No self-supply request");h.succeed(); }
    @GameTest public void weakerRedstoneSourceHasPriorityAndFifteenDisablesLink(GameTestHelper h) { var id=UUID.randomUUID();var a=station(h,P,id,new ItemStack(Items.APPLE,20));var b=station(h,P.east(3),id,new ItemStack(Items.APPLE,20));a.link.behaviour.redstonePowerChanged(10);b.link.behaviour.redstonePowerChanged(2);var requests=LogisticsManager.findPackagersForRequest(h.getLevel(),id,order(Items.APPLE,7),null,"Priority");h.assertTrue(requests.containsKey(b.packager)&&!requests.containsKey(a.packager),"Lower power supplies first");b.link.behaviour.redstonePowerChanged(15);h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),20,"Fifteen disables source");b.link.behaviour.redstonePowerChanged(0);h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),40,"Unpowered link returns immediately");h.succeed(); }
    @GameTest public void actualNeighborSignalUpdatesLinkStateAndDisablesStock(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,12));h.setBlock(P.above().east(),Blocks.REDSTONE_BLOCK);h.assertValueEqual(s.link.behaviour.redstonePower,15,"Neighbor signal reaches link");h.assertTrue(s.link.getBlockState().getValue(PackagerLinkBlock.POWERED),"Powered model");h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),0,"Disabled inventory absent");h.succeed(); }
    @GameTest public void requestSpansPackagersWithOneContextAndFinalFragment(GameTestHelper h) { var id=UUID.randomUUID();var a=station(h,P,id,new ItemStack(Items.APPLE,20));var b=station(h,P.east(3),id,new ItemStack(Items.APPLE,30));a.link.behaviour.redstonePowerChanged(0);b.link.behaviour.redstonePowerChanged(1);h.assertTrue(LogisticsManager.broadcastPackageRequest(h.getLevel(),id,LogisticallyLinkedBehaviour.RequestType.PLAYER,order(Items.APPLE,40),null,"Destination"),"Request issued");h.assertValueEqual(boxed(a.packager),20L,"First source exhausted");h.assertValueEqual(boxed(b.packager),20L,"Second source fills remainder");h.assertValueEqual(PackageItem.getAddress(a.packager.heldBox),"Destination","Address attached");h.assertValueEqual(PackageItem.getOrderId(a.packager.heldBox),PackageItem.getOrderId(b.packager.heldBox),"Shared order ID");h.assertTrue(PackageItem.getOrderContext(a.packager.heldBox)!=null&&PackageItem.getOrderContext(b.packager.heldBox)==null,"Only first box carries context");h.assertFalse(PackageItem.isFinalLink(a.packager.heldBox),"First link not final");h.assertTrue(PackageItem.isFinalLink(b.packager.heldBox)&&PackageItem.isFinal(b.packager.heldBox),"Last source completes order");h.assertValueEqual(b.barrel.getItem(0).getCount(),10,"Remaining ownership conserved");h.succeed(); }
    @GameTest public void duplicateOrderEntriesReserveStockOnlyOnce(GameTestHelper h) { var id=UUID.randomUUID();station(h,P,id,new ItemStack(Items.APPLE,10));var order=new PackageOrderWithCrafts(new PackageOrder(List.of(new BigItemStack(new ItemStack(Items.APPLE),8),new BigItemStack(new ItemStack(Items.APPLE),8))),List.of());var requests=LogisticsManager.findPackagersForRequest(h.getLevel(),id,order,null,"Duplicates");h.assertValueEqual(requests.values().stream().mapToInt(PackagingRequest::getCount).sum(),10,"Reservations cannot exceed actual stock");h.succeed(); }
    @GameTest public void busySourceRejectsWholeBroadcastBeforeOtherSourcesExtract(GameTestHelper h) { var id=UUID.randomUUID();var a=station(h,P,id,new ItemStack(Items.APPLE,20));var b=station(h,P.east(3),id,new ItemStack(Items.APPLE,20));for(int i=0;i<10;i++)b.packager.queuedExitingPackages.add(new BigItemStack(PackageItem.containing(List.of(new ItemStack(Items.CARROT))),1));h.assertFalse(LogisticsManager.broadcastPackageRequest(h.getLevel(),id,LogisticallyLinkedBehaviour.RequestType.RESTOCK,order(Items.APPLE,40),null,"Busy"),"Restock request rejected");h.assertValueEqual(a.barrel.getItem(0).getCount(),20,"Other source unchanged");h.assertValueEqual(b.barrel.getItem(0).getCount(),20,"Busy source unchanged");h.assertTrue(a.packager.heldBox.isEmpty(),"No partial packaging");h.assertFalse(b.packager.isTooBusyFor(LogisticallyLinkedBehaviour.RequestType.PLAYER),"Player has larger source threshold");h.succeed(); }
    @GameTest public void largeOrderProducesSuccessiveBoxIndicesAndConservesStock(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,ItemStack.EMPTY);for(int i=0;i<12;i++)s.barrel.setItem(i,new ItemStack(Items.APPLE,64));LogisticsManager.broadcastPackageRequest(h.getLevel(),id,LogisticallyLinkedBehaviour.RequestType.PLAYER,order(Items.APPLE,700),null,"Bulk");h.assertValueEqual(boxed(s.packager),700L,"Full request boxed");h.assertValueEqual(PackageItem.getIndex(s.packager.heldBox),0,"First fragment");h.assertValueEqual(PackageItem.getIndex(s.packager.queuedExitingPackages.getFirst().stack),1,"Second fragment");h.assertTrue(PackageItem.isFinal(s.packager.queuedExitingPackages.getFirst().stack),"Final source fragment");h.assertValueEqual(java.util.stream.IntStream.range(0,27).map(i->s.barrel.getItem(i).getCount()).sum(),68,"Remainder kept");h.succeed(); }
    @GameTest public void unloadedLinkRetainsPersistentMembershipButNotLiveStock(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,12));var manager=GlobalLogisticsManager.get(h.getLevel());s.link.setRemoved();h.assertValueEqual(manager.getUnloadedLinkCount(id),1,"Unloaded member retained");h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),0,"Removed BE not a live source");s.link.clearRemoved();s.link.initialize();h.assertValueEqual(manager.getUnloadedLinkCount(id),0,"Live membership restored");h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),12,"Stock restored");h.succeed(); }
    @GameTest public void destroyedLastLinkDeletesNetworkAndClearsPackagerLinkedState(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,12));h.setBlock(P.above(),Blocks.AIR);s.packager.recheckIfLinksPresent();h.assertFalse(GlobalLogisticsManager.get(h.getLevel()).isLockable(id),"No links leave no network");h.assertFalse(s.packager.getBlockState().getValue(PackagerBlock.LINKED),"Redstone mode returns");h.succeed(); }
    @GameTest public void changingFrequencyRemovesOldMembershipAndPreservesNewNetwork(GameTestHelper h) { var old=UUID.randomUUID();var next=UUID.randomUUID();var s=station(h,P,old,new ItemStack(Items.APPLE,12));s.link.behaviour.setFrequency(next);var manager=GlobalLogisticsManager.get(h.getLevel());h.assertFalse(manager.isLockable(old),"Old empty network removed");h.assertTrue(manager.isLockable(next),"New network registered");h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),old,new ItemStack(Items.APPLE),null),0,"No stale cached source");h.succeed(); }
    @GameTest public void promiseQueueMatchesComponentsExpiresAndConsumesInOrder(GameTestHelper h) { var changes=new AtomicInteger();var q=new RequestPromiseQueue(changes::incrementAndGet);var named=new ItemStack(Items.APPLE);named.set(DataComponents.CUSTOM_NAME,Component.literal("Named"));q.add(new RequestPromise(new BigItemStack(new ItemStack(Items.APPLE),8)));q.add(new RequestPromise(new BigItemStack(named,9)));q.itemEnteredSystem(new ItemStack(Items.APPLE),3);h.assertValueEqual(q.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),-1),5,"Partial delivery");h.assertValueEqual(q.getTotalPromisedAndRemoveExpired(named,-1),9,"Components independent");q.tick();h.assertValueEqual(q.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),1),0,"Promise expires at exact age");q.forceClear(named);h.assertTrue(q.isEmpty(),"All promises cleared");h.assertTrue(changes.get()>=5,"Partial delivery and age mark data dirty");h.succeed(); }
    @GameTest public void newStockArrivalClearsOnlyPositiveDeltaFromNetworkPromises(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,10));s.packager.getAvailableItems();var q=GlobalLogisticsManager.get(h.getLevel()).getQueuedPromises(id);q.add(new RequestPromise(new BigItemStack(new ItemStack(Items.APPLE),8)));s.barrel.setItem(0,new ItemStack(Items.APPLE,13));s.packager.triggerStockCheck();h.assertValueEqual(q.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),-1),5,"Only three new items fulfill promises");s.packager.triggerStockCheck();h.assertValueEqual(q.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),-1),5,"Repeated scan has no double arrival");s.barrel.setItem(0,new ItemStack(Items.APPLE,4));s.packager.triggerStockCheck();h.assertValueEqual(q.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),-1),5,"Withdrawal does not fulfill");h.succeed(); }
    @GameTest public void savedNetworksPersistOwnerLocksMembersAndPromiseAgeButNotLoadedFlags(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,12));var data=LogisticsNetworkSavedData.load(h.getLevel().getServer());var network=data.getLogisticsNetworks().get(id);network.owner=UUID.randomUUID();network.locked=true;network.panelPromises.add(new RequestPromise(42,new BigItemStack(new ItemStack(Items.APPLE),7)));var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var restored=LogisticsNetworkSavedData.CODEC.parse(ops,LogisticsNetworkSavedData.CODEC.encodeStart(ops,data).getOrThrow()).getOrThrow();var n=restored.getLogisticsNetworks().get(id);h.assertValueEqual(n.owner,network.owner,"Owner persists");h.assertTrue(n.locked&&n.totalLinks.equals(network.totalLinks),"Lock and global positions persist");h.assertTrue(n.loadedLinks.isEmpty(),"Loaded membership is transient");h.assertValueEqual(n.panelPromises.flatten(false).getFirst().ticksExisted,42,"Promise age persists");restored.setDirty(false);n.panelPromises.itemEnteredSystem(new ItemStack(Items.APPLE),1);h.assertTrue(restored.isDirty(),"Deserialized queue remains attached to dirty callback");h.succeed(); }
    @GameTest public void networkLockHonorsOwnerAndNonOwnerPermissions(GameTestHelper h) { var id=UUID.randomUUID();station(h,P,id,ItemStack.EMPTY);var owner=h.makeMockPlayer(GameType.SURVIVAL);var other=h.makeMockPlayer(GameType.SURVIVAL);var manager=GlobalLogisticsManager.get(h.getLevel());manager.logisticsNetworks.get(id).owner=owner.getUUID();h.assertTrue(manager.mayInteract(id,other),"Unlocked network usable");h.assertTrue(manager.setLocked(id,owner,true),"Owner locks");h.assertFalse(manager.mayInteract(id,other),"Locked network rejects others");h.assertFalse(manager.setLocked(id,other,false),"Non-owner cannot change lock");h.assertTrue(manager.mayInteract(id,owner),"Owner still uses network");h.succeed(); }
    @GameTest public void tunedItemRetainsOnlyFrequencyAndSurvivalPlacementUsesIt(GameTestHelper h) { var id=UUID.randomUUID();var stack=new ItemStack(AllBlocks.STOCK_LINK,2);LogisticallyLinkedBlockItem.assignFrequency(stack,null,id);h.assertTrue(stack.hasFoil(),"Tuned item has foil");h.assertValueEqual(LogisticallyLinkedBlockItem.networkFromStack(stack),id,"Frequency stored in native typed BE component");h.setBlock(P.below(),Blocks.STONE);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,2,2));player.setItemInHand(InteractionHand.MAIN_HAND,stack);var hit=new BlockHitResult(Vec3.atCenterOf(h.absolutePos(P.below())).add(0,.5,0),Direction.UP,h.absolutePos(P.below()),false);h.assertTrue(((BlockItem)stack.getItem()).place(new BlockPlaceContext(new UseOnContext(player,InteractionHand.MAIN_HAND,hit))).consumesAction(),"Survival placement");var link=h.getBlockEntity(P,PackagerLinkBlockEntity.class);h.assertValueEqual(link.behaviour.freqId,id,"Placed block adopts only network frequency");h.assertValueEqual(player.getMainHandItem().getCount(),1,"One item consumed");h.succeed(); }
    @GameTest public void linkSaveAndClientTagCarryFrequencyAndNativeEntityType(GameTestHelper h) { var id=UUID.randomUUID();var s=station(h,P,id,ItemStack.EMPTY);var saved=s.link.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(PackagerLinkBlockEntity)BlockEntity.loadStatic(s.link.getBlockPos(),s.link.getBlockState(),saved,h.getLevel().registryAccess());h.assertValueEqual(restored.behaviour.freqId,id,"Frequency round trip");h.assertValueEqual(s.link.getUpdateTag(h.getLevel().registryAccess()).read("Freq",UUIDUtil.CODEC).orElseThrow(),id,"Client receives frequency");h.succeed(); }
    @GameTest public void transactionalStockPreviewCannotFulfillPromisesOrPoisonNetworkCache(GameTestHelper h) {
        var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,10));s.packager.getAvailableItems();var queue=GlobalLogisticsManager.get(h.getLevel()).getQueuedPromises(id);queue.add(new RequestPromise(new BigItemStack(new ItemStack(Items.APPLE),8)));
        try(var tx=Transaction.openOuter()){h.assertValueEqual(s.packager.targetInventory().insert(ItemVariant.of(Items.APPLE),3,tx),3L,"Tentative delivery");h.assertValueEqual(LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true).getCountOf(new ItemStack(Items.APPLE)),13,"Preview sees transactional state");h.assertValueEqual(queue.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),-1),8,"Preview does not fulfill promises");}
        h.assertValueEqual(LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true).getCountOf(new ItemStack(Items.APPLE)),10,"Aborted preview not cached");h.assertValueEqual(queue.getTotalPromisedAndRemoveExpired(new ItemStack(Items.APPLE),-1),8,"Abort leaves promises untouched");h.succeed();
    }
    @GameTest public void accurateAndDisplayCachesUseServerTicksAndCommittedExtractionInvalidatesBoth(GameTestHelper h) {
        var id=UUID.randomUUID();var s=station(h,P,id,new ItemStack(Items.APPLE,20));var manager=GlobalLogisticsManager.get(h.getLevel());var first=LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true);s.barrel.setItem(0,new ItemStack(Items.APPLE,18));h.assertTrue(first==LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true),"One tick snapshot reused");manager.tick();h.assertValueEqual(LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,true).getCountOf(new ItemStack(Items.APPLE)),18,"Accurate summary refreshes next tick");LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,false);LogisticsManager.broadcastPackageRequest(h.getLevel(),id,LogisticallyLinkedBehaviour.RequestType.PLAYER,order(Items.APPLE,7),null,"Refresh");h.assertValueEqual(LogisticsManager.getSummaryOfNetwork(h.getLevel(),id,false).getCountOf(new ItemStack(Items.APPLE)),11,"Committed packaging invalidates display cache immediately");h.succeed();
    }
    @GameTest public void oneNetworkAggregatesLoadedLinksAcrossServerDimensions(GameTestHelper h) {
        var id=UUID.randomUUID();station(h,P,id,new ItemStack(Items.APPLE,11));var other=h.getLevel().getServer().getLevel(net.minecraft.world.level.Level.NETHER);var pos=new BlockPos(25000,80,25000);other.getChunk(pos);other.setBlockAndUpdate(pos.north(),Blocks.BARREL.defaultBlockState());((BarrelBlockEntity)other.getBlockEntity(pos.north())).setItem(0,new ItemStack(Items.APPLE,13));other.setBlockAndUpdate(pos,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));other.setBlockAndUpdate(pos.above(),AllBlocks.STOCK_LINK.defaultBlockState());var link=(PackagerLinkBlockEntity)other.getBlockEntity(pos.above());link.behaviour.setFrequency(id);link.initialize();
        h.assertValueEqual(LogisticsManager.getStockOf(h.getLevel(),id,new ItemStack(Items.APPLE),null),24,"Source rules allow cross-dimensional network");var network=GlobalLogisticsManager.get(h.getLevel()).logisticsNetworks.get(id);h.assertTrue(network.totalLinks.stream().anyMatch(p->p.dimension()==net.minecraft.world.level.Level.NETHER),"Dimension preserved in global positions");other.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());other.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());other.setBlockAndUpdate(pos.north(),Blocks.AIR.defaultBlockState());h.succeed();
    }
    @GameTest public void actualSavedDataStorageReloadKeepsPromisesAndOwnerWithoutRuntimeLinks(GameTestHelper h) {
        var id=UUID.randomUUID();station(h,P,id,new ItemStack(Items.APPLE,11));var server=h.getLevel().getServer();var data=LogisticsNetworkSavedData.load(server);data.getLogisticsNetworks().get(id).panelPromises.add(new RequestPromise(17,new BigItemStack(new ItemStack(Items.APPLE),8)));server.overworld().getDataStorage().saveAndJoin();
        try(var disk=new net.minecraft.world.level.storage.SavedDataStorage(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("dimensions/minecraft/overworld/data"),net.minecraft.util.datafix.DataFixers.getDataFixer(),h.getLevel().registryAccess())){
            var restored=disk.get(LogisticsNetworkSavedData.TYPE);h.assertTrue(restored!=null&&restored.getLogisticsNetworks().containsKey(id),"Native storage reads saved network from disk");var n=restored.getLogisticsNetworks().get(id);h.assertValueEqual(n.panelPromises.flatten(false).getFirst().ticksExisted,17,"Native storage retains age");h.assertTrue(n.loadedLinks.isEmpty(),"Disk does not persist live runtime membership");
        }h.succeed();
    }
}
